class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int prefix = 0;
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            prefix += (nums[i] == 1 ? 1 : -1);
            if (seen.count(prefix)) {
                ans = max(ans, i - seen[prefix]);
            } else {
                seen[prefix] = i;
            }
        }
        return ans;
    }
};

class Solution {
    public int findMaxLength(int[] nums) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, -1);
        int prefix = 0;
        int ans = 0;
        for (int i = 0; i < nums.length; i++) {
            prefix += (nums[i] == 1 ? 1 : -1);
            if (seen.containsKey(prefix)) {
                ans = Math.max(ans, i - seen.get(prefix));
            } else {
                seen.put(prefix, i);
            }
        }
        return ans;
    }
}

var findMaxLength = function(nums) {
    const seen = new Map();
    seen.set(0, -1);
    let prefix = 0;
    let ans = 0;
    for (let i = 0; i < nums.length; i++) {
        prefix += nums[i] === 1 ? 1 : -1;
        if (seen.has(prefix)) {
            ans = Math.max(ans, i - seen.get(prefix));
        } else {
            seen.set(prefix, i);
        }
    }
    return ans;
};
